def s_common_templates(*, claims: ClaimCollection):
    cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.structural.set")
    cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.navigation.set")
    cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.note-links.set")
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.all-groups-cover-all-observed",
    )
    cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.other.set")
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.modag.only-in-nusach-param2",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.sh.only-in-nusach-param2",
    )

    kq_rows = kq_am2_common.with_dedicated_page_link(
        cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.kq.set"),
        doc_name=_KQ_AM2_DOC,
    )
    kq_rows = dedicated_rows.with_kq_special_dedicated_page_link(
        kq_rows,
        doc_name=_KQ_SPECIAL_DOC,
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.kq-special.subtype-counts",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.kq-am2.sug-values",
    )
    json_kq = cmn.emit_claim_by_id(claims=claims, claim_id="mp.plain.example.kq")
    special_letter_rows = cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.special-letters.set",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.accents.set",
    )
    jer_rows = cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.plain.templates.jerusalem.set",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.poetic.set",
    )

    plain_accent_rows = cmn.accent_rows_for_templates(_PLAIN_ACCENT_TEMPLATES)
    plain_choice_rows = dedicated_rows.with_kaful_dedicated_page_link(
        cmn.accent_rows_for_templates(_CHOICE_TEMPLATES),
        doc_name=_KAFUL_DOC,
    )
    plain_multimark_rows = [
        *cmn.accent_rows_for_templates(_MULTIMARK_TEMPLATES[:2]),
        *cmn.other_rows_for_templates(_MULTIMARK_TEMPLATES[2:]),
        *jer_rows,
    ]
    whitespace_poetic_rows = cmn.poetic_rows_for_templates(
        ["ר1", "ר2", "ר3", "ר4", "ר0"]
    )
    whitespace_extra_rows = cmn.other_rows_for_templates(["רווח בסוף שורה"])
    other_templates_rows = (
        [cmn.good_ending_row(good_ending_doc=_GOOD_ENDING_TMPL_DOC)]
        + cmn.poetic_rows_for_templates(["פרשה-מרכז"])
        + [
            *cmn.accent_rows_for_templates(["גלגל-2", "ירח בן יומו-2"]),
            *cmn.other_rows_for_templates(["מ:אות מנוקדת"]),
        ]
    )

    _emit_claim_payload(
        claims,
        "mp.plain.docs.common-templates.templates-in-plain-survey",
        None,
        kind="enum",
        subject="mp:plain",
        data={"templates": _PLAIN_COMMON_TEMPLATES},
    )
    sheets_link = author.anchor_h("Templates tab", cmn.SHEETS_TMPL)
    sheets_data_link = author.anchor_h("$MAM Google Sheet", cmn.SHEETS_DATA)
    return [
        author.heading_level_2("Selected templates"),
        author.para(
            [
                "For English and Hebrew descriptions of most templates, see the ",
                sheets_link,
                " of the ",
                sheets_data_link,
                ".",
            ]
        ),
        author.heading_level_3("$Ketiv_qere templates"),
        author.std_table(kq_rows, arg_to_troh=["Template", "Purpose"]),
        author.para("Example of standard $ketiv_qere:"),
        json_block.json_block_raw_html(json_kq),
        author.heading_level_3("Special letter templates"),
        author.std_table(special_letter_rows, arg_to_troh=["Template", "Purpose"]),
        author.heading_level_3("Punctuation templates"),
        author.std_table(
            plain_accent_rows,
            arg_to_troh=["Template", "Purpose"],
        ),
        author.heading_level_3("Multimark templates"),
        author.std_table(
            plain_multimark_rows,
            arg_to_troh=["Template", "Purpose"],
        ),
        author.heading_level_3("Choice templates"),
        author.para(
            "Most applications will need to make a choice between the two or three options"
            " presented by these templates."
        ),
        author.std_table(
            plain_choice_rows,
            arg_to_troh=["Template", "Purpose"],
        ),
        author.heading_level_3("Whitespace templates"),
        author.std_table(
            cmn.whitespace_rows_shared()
            + whitespace_poetic_rows
            + whitespace_extra_rows,
            arg_to_troh=["Template", "Purpose"],
        ),
        author.para(
            "Many editions will choose to skip poetic formatting by treating"
            " ר0–ר4 as simple word spaces."
        ),
        author.heading_level_3("Note template"),
        author.std_table(
            [cmn.NOTE_ROW_PLAIN],
            arg_to_troh=["Template", "Purpose"],
        ),
        author.heading_level_3("Documentation templates"),
        author.std_table(
            cmn.other_rows_shared_core(nusach_doc=_NUSACH_DOC),
            arg_to_troh=["Template", "Purpose"],
        ),
        author.heading_level_3("Other templates"),
        author.std_table(
            other_templates_rows,
            arg_to_troh=["Template", "Purpose"],
        ),
    ]


def s_pseudo_verses():
    return [
        author.heading_level_2("Pseudo-verses (0 and תתת)"),
        author.para(
            [
                "The ",
                mb_html.code('"0"'),
                " and ",
                author.hbo('"תתת"'),
                " keys are pseudo-verses that contain"
                " Wiki-specific navigation and formatting markup, not biblical text."
                " They can generally be skipped when extracting verse content.",
            ]
        ),
        author.unordered_list(
            [
                [
                    mb_html.code('"0"'),
                    ": Contains ",
                    mb_html.code("noinclude"),
                    " tags, navigation templates, margin settings.",
                ],
                [
                    author.hbo('"תתת"'),
                    ": Contains end-of-chapter markers, unnumbered-verse section.",
                ],
            ]
        ),
    ]
